            curr = list1[i]
            i += 1
        else:
            curr = list2[j]
            j += 1

    return (prev + curr) / 2.0

def max_difference(tuple_list):
    if not tuple_list:
        return 0
    return max(abs(a - b) for a, b in tuple_list)

def find_first_occurrence(arr, target):
    left = 0
    right = len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            result = mid
            right = mid - 1
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return result

