def find_combinations(tuple_list):
    result = []
    for i in range(len(tuple_list)):
        for j in range(i + 1, len(tuple_list)):
            result.append(tuple(x + y for x, y in zip(tuple_list[i], tuple_list[j])))
    return result

def _sum(arr):
    total = 0
    for value in arr:
        total += value
    return total

def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0

    for k in range(1, n + 1):
        if n % k == 0 and s[:k] * (n // k) == s:
            return k

    return n
